// Command widegen writes the generated files of the package wide.
//
// Run it with "go generate ./internal/wide", which runs it in the folder of
// the package. The flag -all turns on the SIMD code of every method, so that
// a benchmark can measure it. Do not commit the files that -all writes. It reads the scalar code of each vector type, in the plain
// functions of the hand-written file of the type, such as f32x8.go. A plain
// function whose doc comment starts with "addF32x8 is the scalar code of
// F32x8.Add." gives the method F32x8.Add, and the rest of its doc comment
// becomes the doc comment of the method.
//
// For each vector type T, such as f32x8, widegen writes these files:
//
//	T_scalar.go       the methods in a build without the SIMD implementation
//	T_simd.go         the methods in the SIMD build
//	T_simd_amd64.go   the SIMD code on amd64, if T has SIMD code
//	T_simd_128.go     the SIMD code on arm64 and wasm, if T has SIMD code
//
// Each generated file starts with the line
// "// Code generated by widegen. DO NOT EDIT." Do not edit such a file. Edit
// the plain functions or the table of this program, and run widegen again.
//
// These files of the package are written by hand: the file of each type
// (f32x4.go, f32x8.go, f32x16.go, i32x4.go, i32x8.go, u32x4.go, u32x8.go,
// u16x16.go), convert.go, doc.go, wide.go, the CPU checks
// (cpu_simd_amd64.go, cpu_simd_arm64.go, cpu_simd_wasm.go) and the helpers of
// the SIMD code (wide_simd_amd64.go, wide_simd_128.go).
//
// The table below lists, for each method, the SIMD code and whether the SIMD
// build uses it. A method whose SIMD code is off calls its scalar code
// directly in the SIMD build too, with no check of useSIMD. The SIMD code is
// on only where a benchmark on amd64 showed it at least 1.2 times as fast as
// the scalar build. A method loads its arrays into vectors and stores the
// result back, and for a single operation that costs more than the
// operation saves. arm64 and wasm use the same choice, because they were not
// measured. To measure again, run widegen with -all, run the benchmarks in
// both builds, set the table, and run widegen without -all.
package main

import (
	"bytes"
	"flag"
	"fmt"
	"go/ast"
	"go/format"
	"go/parser"
	"go/printer"
	"go/token"
	"log"
	"os"
	"path/filepath"
	"regexp"
	"strconv"
	"strings"
)

// header is the first line of each generated file.
const header = "// Code generated by widegen. DO NOT EDIT.\n\n"

// The build tags of the generated files.
const (
	tagScalar = "//go:build !goexperiment.simd || okage_scalar || tinygo || !(amd64 || arm64 || wasm)"
	tagSIMD   = "//go:build goexperiment.simd && !okage_scalar && !tinygo && (amd64 || arm64 || wasm)"
	tagAMD64  = "//go:build goexperiment.simd && !okage_scalar && !tinygo"
	tag128    = "//go:build goexperiment.simd && !okage_scalar && !tinygo && (arm64 || wasm)"
)

// f32x16, u16x16 and blend are names that the table and the code use more than once.
const (
	f32x16 = "F32x16"
	u16x16 = "U16x16"
	blend  = "Blend"
)

// types lists the vector types in the order of their files.
var types = []string{"F32x4", "F32x8", f32x16, "I32x4", "I32x8", "U32x4", "U32x8", u16x16}

// kernel is the SIMD code of one method. args gives the kind of each vector
// argument and ret the kind of the result: F for float32 lanes, I for int32,
// U for uint32 and H for uint16. body holds the statements, and its last
// line is the result. In body, {W} stands for the number of lanes of one
// vector. A vector argument is x, y or z.
type kernel struct {
	method string
	on     bool
	args   string
	ret    byte
	body   []string
	// name is the name of the SIMD function, if it is not the name of the
	// plain function with the suffix SIMD.
	name string
	// dispatch is the code that calls the SIMD function in the method, if
	// it is not a plain call.
	dispatch string
}

func bin(method string, on bool, op string) kernel {
	return kernel{method: method, on: on, args: "FF", ret: 'F', body: []string{"x." + op + "(y)"}}
}

func bit(method string, on bool, op string) kernel {
	return kernel{method: method, on: on, args: "FF", ret: 'F', body: []string{"x.ToBits()." + op + "(y.ToBits()).BitsToFloat32()"}}
}

func cmp(method string, on bool, op string) kernel {
	return kernel{method: method, on: on, args: "FF", ret: 'F', body: []string{"maskF{W}(x." + op + "(y))"}}
}

func unary(method string, on bool, ret byte, body ...string) kernel {
	return kernel{method: method, on: on, args: "F", ret: ret, body: body}
}

func ibin(method string, on bool, kind, op string) kernel {
	return kernel{method: method, on: on, args: kind + kind, ret: kind[0], body: []string{"x." + op + "(y)"}}
}

// floatKernels gives the kernels that F32x4 and F32x8 share. abs and not say
// whether Abs and Not are on, because they are faster only for F32x4.
func floatKernels(abs, not bool) []kernel {
	return []kernel{
		unary("Floor", true, 'F', "vFloor{W}(x)"),
		unary("Abs", abs, 'F', "x.ToBits().And(archsimd.BroadcastUint32x{W}(0x7fffffff)).BitsToFloat32()"),
		{method: "Max", args: "FF", ret: 'F', body: []string{"vMax{W}(x, y)"}},
		{method: "Min", args: "FF", ret: 'F', body: []string{"vMin{W}(x, y)"}},
		cmp("CmpEq", false, "Equal"),
		cmp("CmpNe", false, "NotEqual"),
		cmp("CmpGe", false, "GreaterEqual"),
		cmp("CmpGt", false, "Greater"),
		cmp("CmpLe", false, "LessEqual"),
		cmp("CmpLt", false, "Less"),
		{method: blend, args: "FFF", ret: 'F', body: []string{"z.ToBits().Xor(z.ToBits().Xor(y.ToBits()).And(x.ToBits())).BitsToFloat32()"}},
		unary("Round", true, 'F', "vRound{W}(x)"),
		unary("RoundInt", true, 'I', "vTrunc{W}(vRound{W}(x))"),
		unary("TruncInt", false, 'I', "vTrunc{W}(x)"),
		unary("RecipFast", false, 'F', "archsimd.BroadcastFloat32x{W}(1).Div(x)"),
		unary("RecipSqrt", false, 'F', "archsimd.BroadcastFloat32x{W}(1).Div(x.Sqrt())"),
		unary("Sqrt", false, 'F', "x.Sqrt()"),
		bin("Add", false, "Add"),
		bin("Sub", false, "Sub"),
		bin("Mul", false, "Mul"),
		bin("Div", false, "Div"),
		bit("And", false, "And"),
		bit("Or", false, "Or"),
		bit("Xor", false, "Xor"),
		unary("Neg", false, 'F', "archsimd.Float32x{W}{}.Sub(x)"),
		unary("Not", not, 'F', "x.ToBits().Not().BitsToFloat32()"),
	}
}

// table gives the kernels of each type.
var table = map[string][]kernel{
	"F32x4": floatKernels(true, true),
	"F32x8": append(floatKernels(false, false),
		unary("Fract", true, 'F', "x.Sub(vFloor{W}(x))"),
		unary("Normalize", true, 'F', "vMin{W}(vMax{W}(x, archsimd.Float32x{W}{}), archsimd.BroadcastFloat32x{W}(1))"),
		unary("IsFinite", true, 'F',
			"expMask := archsimd.BroadcastUint32x{W}(0xFF000000)",
			"shiftU := x.ToBits().ShiftAllLeft(1).And(expMask)",
			"shiftU.Equal(expMask).ToInt32x{W}().Not().ToBits().BitsToFloat32()"),
		unary("Powf", true, 'F',
			"e := x.ToBits().BitsToInt32().ConvertToFloat32().Mul(archsimd.BroadcastFloat32x{W}(1.0 / (1 << 23)))",
			"m := x.ToBits().And(archsimd.BroadcastUint32x{W}(0x007fffff)).Or(archsimd.BroadcastUint32x{W}(0x3f000000)).BitsToFloat32()",
			"log2X := e.Sub(archsimd.BroadcastFloat32x{W}(124.225514990))",
			"log2X = log2X.Sub(archsimd.BroadcastFloat32x{W}(1.498030302).Mul(m))",
			"log2X = log2X.Sub(archsimd.BroadcastFloat32x{W}(1.725879990).Div(archsimd.BroadcastFloat32x{W}(0.3520887068).Add(m)))",
			"p := log2X.Mul(archsimd.BroadcastFloat32x{W}(exp))",
			"f := p.Sub(vFloor{W}(p))",
			"q := p.Add(archsimd.BroadcastFloat32x{W}(121.274057500))",
			"q = q.Sub(f.Mul(archsimd.BroadcastFloat32x{W}(1.490129070)))",
			"q = q.Add(archsimd.BroadcastFloat32x{W}(27.728023300).Div(archsimd.BroadcastFloat32x{W}(4.84252568).Sub(f)))",
			"q = q.Mul(archsimd.BroadcastFloat32x{W}(1 << 23))",
			"q = vMin{W}(vMax{W}(q, archsimd.Float32x{W}{}), archsimd.BroadcastFloat32x{W}(infBits))",
			"res := vTrunc{W}(vRound{W}(q)).ToBits().BitsToFloat32()",
			"skip := x.Equal(archsimd.Float32x{W}{}).Or(x.Equal(archsimd.BroadcastFloat32x{W}(1)))",
			"x.IfElse(skip, res)"),
	),
	f32x16: {
		unary("Abs", false, 'F', "x.ToBits().And(archsimd.BroadcastUint32x{W}(0x7fffffff)).BitsToFloat32()"),
		cmp("CmpGt", false, "Greater"),
		{method: blend, args: "FFF", ret: 'F', body: []string{"z.ToBits().Xor(z.ToBits().Xor(y.ToBits()).And(x.ToBits())).BitsToFloat32()"}},
		unary("Normalize", true, 'F', "vMin{W}(vMax{W}(x, archsimd.Float32x{W}{}), archsimd.BroadcastFloat32x{W}(1))"),
		unary("Floor", true, 'F',
			"rd := vRound{W}(x)",
			"rd.Sub(maskF{W}(rd.Greater(x)).ToBits().And(archsimd.BroadcastFloat32x{W}(1).ToBits()).BitsToFloat32())"),
		unary("Sqrt", true, 'F', "x.Sqrt()"),
		unary("Round", true, 'F', "vRound{W}(x)"),
		{
			method: "SaveToU16x16", on: false, args: "F", ret: 'I', name: "clampU16F32x16SIMD",
			body:     []string{"vTrunc{W}(vMin{W}(vMax{W}(archsimd.Float32x{W}{}, x), archsimd.BroadcastFloat32x{W}(65535)))"},
			dispatch: "for i, l := range clampU16F32x16SIMD(v) {\n\tdst[i] = uint16(l)\n}\nreturn",
		},
		bin("Add", false, "Add"),
		bin("Sub", false, "Sub"),
		bin("Mul", false, "Mul"),
	},
	"I32x4": intKernels("ToF32x4"),
	"I32x8": intKernels("ToF32x8"),
	"U32x4": uintKernels(),
	"U32x8": uintKernels(),
	u16x16: {
		ibin("Min", false, "H", "Min"),
		ibin("Max", false, "H", "Max"),
		{method: "CmpLe", args: "HH", ret: 'H', body: []string{"x.LessEqual(y).ToInt16x{W}().ToBits()"}},
		{method: blend, on: true, args: "HHH", ret: 'H', body: []string{"y.And(x).Or(z.AndNot(x))"}},
		ibin("Add", false, "H", "Add"),
		ibin("Sub", false, "H", "Sub"),
		ibin("Mul", false, "H", "Mul"),
		ibin("And", false, "H", "And"),
		ibin("Or", false, "H", "Or"),
		{method: "Not", args: "H", ret: 'H', body: []string{"x.Not()"}},
	},
}

func intKernels(toF32 string) []kernel {
	return []kernel{
		{method: blend, args: "III", ret: 'I', body: []string{"z.Xor(z.Xor(y).And(x))"}},
		{method: "CmpEq", args: "II", ret: 'I', body: []string{"x.Equal(y).ToInt32x{W}()"}},
		{method: "CmpGt", args: "II", ret: 'I', body: []string{"x.Greater(y).ToInt32x{W}()"}},
		{method: "CmpLt", args: "II", ret: 'I', body: []string{"x.Less(y).ToInt32x{W}()"}},
		{method: toF32, args: "I", ret: 'F', body: []string{"x.ConvertToFloat32()"}},
		ibin("Add", false, "I", "Add"),
		ibin("And", false, "I", "And"),
		ibin("Mul", false, "I", "Mul"),
		ibin("Or", false, "I", "Or"),
		ibin("Xor", false, "I", "Xor"),
	}
}

func uintKernels() []kernel {
	return []kernel{
		{method: "CmpEq", args: "UU", ret: 'U', body: []string{"x.Equal(y).ToInt32x{W}().ToBits()"}},
		{method: "Shl", args: "U", ret: 'U', body: []string{"x.ShiftAllLeft(uint64(rhs & 31))"}},
		{method: "Shr", args: "U", ret: 'U', body: []string{"x.ShiftAllRight(uint64(rhs & 31))"}},
		{method: "Not", args: "U", ret: 'U', body: []string{"x.Not()"}},
		ibin("Add", false, "U", "Add"),
		ibin("And", false, "U", "And"),
		ibin("Or", false, "U", "Or"),
	}
}

// method is a method of a vector type, from its plain function.
type method struct {
	name   string   // the name of the method, such as Add
	plain  string   // the name of the plain function, such as addF32x8
	params []param  // the params after the receiver
	ret    string   // the result type, or "" for none
	doc    []string // the doc comment of the method, as lines
}

// param is one parameter of a method.
type param struct {
	name, typ string
}

// docRE matches the first line of the doc comment of a plain function.
var docRE = regexp.MustCompile(`^// (\w+) is the scalar code of (\w+)\.(\w+)\.$`)

// readMethods reads the methods of typ from the plain functions of its file.
func readMethods(dir, typ string) ([]method, error) {
	fset := token.NewFileSet()
	name := filepath.Join(dir, strings.ToLower(typ)+".go")
	f, err := parser.ParseFile(fset, name, nil, parser.ParseComments)
	if err != nil {
		return nil, fmt.Errorf("parsing %s: %w", name, err)
	}
	var out []method
	for _, d := range f.Decls {
		fd, ok := d.(*ast.FuncDecl)
		if !ok || fd.Recv != nil || fd.Doc == nil {
			continue
		}
		m := docRE.FindStringSubmatch(fd.Doc.List[0].Text)
		if m == nil || m[1] != fd.Name.Name || m[2] != typ {
			continue
		}
		var doc []string
		for i, c := range fd.Doc.List {
			if c.Text == "//" {
				for _, l := range fd.Doc.List[i+1:] {
					doc = append(doc, l.Text)
				}
				break
			}
		}
		if len(doc) == 0 {
			return nil, fmt.Errorf("%s: %s has no doc comment for the method", name, fd.Name.Name)
		}
		var params []param
		for _, field := range fd.Type.Params.List {
			t := nodeString(fset, field.Type)
			for _, n := range field.Names {
				params = append(params, param{n.Name, t})
			}
		}
		if len(params) == 0 || params[0].typ != typ {
			return nil, fmt.Errorf("%s: the first param of %s is not a %s", name, fd.Name.Name, typ)
		}
		ret := ""
		if fd.Type.Results != nil {
			ret = nodeString(fset, fd.Type.Results.List[0].Type)
		}
		out = append(out, method{name: m[3], plain: m[1], params: params[1:], ret: ret, doc: doc})
	}
	return out, nil
}

func nodeString(fset *token.FileSet, n ast.Node) string {
	var b bytes.Buffer
	if err := printer.Fprint(&b, fset, n); err != nil {
		log.Fatal(err)
	}
	return b.String()
}

// sig gives the signature of m as a method of typ.
func (m method) sig(typ string) string {
	var groups []string
	for i := 0; i < len(m.params); {
		j := i
		var names []string
		for j < len(m.params) && m.params[j].typ == m.params[i].typ {
			names = append(names, m.params[j].name)
			j++
		}
		groups = append(groups, strings.Join(names, ", ")+" "+m.params[i].typ)
		i = j
	}
	s := fmt.Sprintf("func (v %s) %s(%s)", typ, m.name, strings.Join(groups, ", "))
	if m.ret != "" {
		s += " " + m.ret
	}
	return s
}

// args gives the arguments of the plain function of m.
func (m method) args() string {
	names := []string{"v"}
	for _, p := range m.params {
		names = append(names, p.name)
	}
	return strings.Join(names, ", ")
}

// call gives the statement that calls f with the args of m.
func (m method) call(f string) string {
	if m.ret == "" {
		return f + "(" + m.args() + ")"
	}
	return "return " + f + "(" + m.args() + ")"
}

func findKernel(typ, name string) (kernel, bool) {
	for _, k := range table[typ] {
		if k.method == name {
			return k, true
		}
	}
	return kernel{}, false
}

func scalarFile(typ string, ms []method) string {
	var b strings.Builder
	fmt.Fprintf(&b, "%s%s\n\npackage wide\n\n", header, tagScalar)
	fmt.Fprintf(&b, "// This file holds the methods of %s in a build without the SIMD\n// implementation. Each method calls its scalar code in %s.go.\n", typ, strings.ToLower(typ))
	for _, m := range ms {
		fmt.Fprintf(&b, "\n%s\n%s {\n\t%s\n}\n", strings.Join(m.doc, "\n"), m.sig(typ), m.call(m.plain))
	}
	return b.String()
}

func simdFile(typ string, ms []method) string {
	var b strings.Builder
	fmt.Fprintf(&b, "%s%s\n\npackage wide\n\n", header, tagSIMD)
	fmt.Fprintf(&b, "// This file holds the methods of %s in the SIMD build. A method with SIMD\n"+
		"// code runs it if useSIMD is true, and its scalar code in %s.go if not.\n"+
		"// A method without SIMD code always runs its scalar code.\n", typ, strings.ToLower(typ))
	for _, m := range ms {
		fmt.Fprintf(&b, "\n%s\n%s {\n", strings.Join(m.doc, "\n"), m.sig(typ))
		if k, ok := findKernel(typ, m.name); ok && k.on {
			d := k.dispatch
			if d == "" {
				d = m.call(kernelName(k, m))
			}
			fmt.Fprintf(&b, "\tif useSIMD {\n\t\t%s\n\t}\n", strings.ReplaceAll(d, "\n", "\n\t\t"))
		}
		fmt.Fprintf(&b, "\t%s\n}\n", m.call(m.plain))
	}
	return b.String()
}

func kernelName(k kernel, m method) string {
	if k.name != "" {
		return k.name
	}
	return m.plain + "SIMD"
}

// lanes gives the number of lanes of typ.
func lanes(typ string) int {
	n, err := strconv.Atoi(typ[strings.LastIndex(typ, "x")+1:])
	if err != nil {
		log.Fatalf("the type %s has no number of lanes", typ)
	}
	return n
}

// kindInfo gives the lane type, the name in archsimd and the prefix of the
// load helper of a kind.
func kindInfo(k byte) (elem, simd, load string) {
	switch k {
	case 'F':
		return "float32", "Float32", "ldF"
	case 'I':
		return "int32", "Int32", "ldI"
	case 'U':
		return "uint32", "Uint32", "ldU"
	}
	return "uint16", "Uint16", "ldH"
}

// goType gives the Go type of a vector of kind k with n lanes.
func goType(k byte, n int) string {
	switch {
	case k == 'F' && n == 16:
		return f32x16
	case k == 'F':
		return fmt.Sprintf("F32x%d", n)
	case k == 'I' && n == 16:
		return "[16]int32"
	case k == 'I':
		return fmt.Sprintf("I32x%d", n)
	case k == 'U':
		return fmt.Sprintf("U32x%d", n)
	}
	return u16x16
}

// slices gives the slice expressions of the parts of a value of type t with
// n lanes, for vectors of w lanes.
func slices(t string, n, w int) []string {
	if n == w {
		return []string{"[:]"}
	}
	var out []string
	for off := 0; off < n; off += w {
		if t == f32x16 {
			h, o := off/8, off%8
			if w == 8 {
				out = append(out, fmt.Sprintf("[%d][:]", h))
			} else if o == 0 {
				out = append(out, fmt.Sprintf("[%d][:%d]", h, w))
			} else {
				out = append(out, fmt.Sprintf("[%d][%d:]", h, o))
			}
			continue
		}
		switch {
		case off == 0:
			out = append(out, fmt.Sprintf("[:%d]", w))
		case off+w == n:
			out = append(out, fmt.Sprintf("[%d:]", off))
		default:
			out = append(out, fmt.Sprintf("[%d:%d]", off, off+w))
		}
	}
	return out
}

func kernelFunc(typ string, k kernel, m method, width int) string {
	n := lanes(typ)
	w := width
	vnames := []string{"a", "b", "c"}[:len(k.args)]
	xnames := []string{"x", "y", "z"}[:len(k.args)]
	var params []string
	for i := range k.args {
		params = append(params, vnames[i]+" "+goType(k.args[i], n))
	}
	var extra []param
	for _, p := range m.params {
		if p.typ != typ && !strings.HasPrefix(p.typ, "*") {
			extra = append(extra, p)
		}
	}
	var decl, names strings.Builder
	for _, p := range extra {
		decl.WriteString(", " + p.name + " " + p.typ)
		names.WriteString(", " + p.name)
	}
	extraDecl, extraNames := decl.String(), names.String()
	name := kernelName(k, m)
	rett := goType(k.ret, n)
	body := k.body
	sub := func(s string) string { return strings.ReplaceAll(s, "{W}", strconv.Itoa(w)) }
	inParts := slices(goType(k.args[0], n), n, w)
	outParts := slices(rett, n, w)
	var b strings.Builder
	if len(inParts) > 1 && len(body) > 1 {
		hname := strings.TrimSuffix(name, "SIMD") + fmt.Sprintf("Lanes%d", w)
		var hp []string
		for i := range k.args {
			_, s, _ := kindInfo(k.args[i])
			hp = append(hp, fmt.Sprintf("%s archsimd.%sx%d", xnames[i], s, w))
		}
		_, rs, _ := kindInfo(k.ret)
		fmt.Fprintf(&b, "// %s is %s for %d lanes.\nfunc %s(%s%s) archsimd.%sx%d {\n", hname, name, w, hname, strings.Join(hp, ", "), extraDecl, rs, w)
		for _, l := range body[:len(body)-1] {
			fmt.Fprintf(&b, "\t%s\n", sub(l))
		}
		fmt.Fprintf(&b, "\treturn %s\n}\n\n", sub(body[len(body)-1]))
		body = []string{hname + "(" + strings.Join(xnames, ", ") + extraNames + ")"}
	}
	doc := fmt.Sprintf("// %s is the SIMD code of %s.%s.", name, typ, m.name)
	if k.name != "" {
		doc = fmt.Sprintf("// %s is the SIMD code of %s.%s, without the store in dst.", name, typ, m.name)
	}
	fmt.Fprintf(&b, "%s\nfunc %s(%s%s) %s {\n\tvar r %s\n", doc, name, strings.Join(params, ", "), extraDecl, rett, rett)
	relem, _, _ := kindInfo(k.ret)
	for p := range inParts {
		ind := "\t"
		if len(inParts) > 1 {
			b.WriteString("\t{\n")
			ind = "\t\t"
		}
		for i := range k.args {
			_, _, ld := kindInfo(k.args[i])
			fmt.Fprintf(&b, "%s%s := %s%d(%s%s)\n", ind, xnames[i], ld, w, vnames[i], inParts[p])
		}
		for _, l := range body[:len(body)-1] {
			fmt.Fprintf(&b, "%s%s\n", ind, sub(l))
		}
		fmt.Fprintf(&b, "%s%s.StoreArray((*[%d]%s)(r%s))\n", ind, sub(body[len(body)-1]), w, relem, outParts[p])
		if len(inParts) > 1 {
			b.WriteString("\t}\n")
		}
	}
	b.WriteString("\treturn r\n}\n")
	return b.String()
}

// nativeWidth gives the lanes of one vector for typ on amd64 or on 128-bit
// vectors.
func nativeWidth(typ string, amd64 bool) int {
	switch {
	case typ == u16x16 && amd64:
		return 16
	case typ == u16x16:
		return 8
	case amd64 && lanes(typ) >= 8:
		return 8
	}
	return 4
}

func kernelFile(typ string, ms []method, amd64 bool) string {
	var funcs []string
	for _, m := range ms {
		k, ok := findKernel(typ, m.name)
		if !ok || !k.on {
			continue
		}
		funcs = append(funcs, kernelFunc(typ, k, m, nativeWidth(typ, amd64)))
	}
	if len(funcs) == 0 {
		return ""
	}
	all := strings.Join(funcs, "\n")
	tag, desc := tagAMD64, "on amd64. The SIMD code runs only on a CPU with AVX2."
	if !amd64 {
		tag, desc = tag128, "on arm64 and wasm, where a vector holds 128 bits."
		if lanes(typ) > nativeWidth(typ, false) {
			desc += " Each part of the lanes is one vector."
		}
	}
	var b strings.Builder
	fmt.Fprintf(&b, "%s%s\n\npackage wide\n\n", header, tag)
	if strings.Contains(all, "archsimd.") {
		b.WriteString("import \"simd/archsimd\"\n\n")
	}
	b.WriteString(wrapComment("This file holds the SIMD code of the methods of "+typ+" "+desc) + "\n")
	if strings.Contains(all, "infBits") {
		b.WriteString("\n// infBits is the bits of +Inf as a float32 value, as in f32x8::powf.\nconst infBits = float32(0x7f800000)\n")
	}
	b.WriteString("\n" + all)
	return b.String()
}

// wrapComment wraps s into comment lines of at most 78 columns.
func wrapComment(s string) string {
	var lines []string
	line := "//"
	for w := range strings.FieldsSeq(s) {
		if len(line)+1+len(w) > 78 {
			lines = append(lines, line)
			line = "//"
		}
		line += " " + w
	}
	return strings.Join(append(lines, line), "\n")
}

func main() {
	dir := flag.String("dir", ".", "the folder of the package wide")
	out := flag.String("out", "", "the folder to write the files to (default: -dir)")
	all := flag.Bool("all", false, "turn on the SIMD code of every method, to measure it")
	flag.Parse()
	if *all {
		for typ, ks := range table {
			for i := range ks {
				table[typ][i].on = true
			}
		}
	}
	if *out == "" {
		*out = *dir
	}
	for _, typ := range types {
		ms, err := readMethods(*dir, typ)
		if err != nil {
			log.Fatal(err)
		}
		for _, k := range table[typ] {
			found := false
			for _, m := range ms {
				found = found || m.name == k.method
			}
			if !found {
				log.Fatalf("%s.%s is in the table, but %s.go has no plain function for it", typ, k.method, strings.ToLower(typ))
			}
		}
		base := filepath.Join(*out, strings.ToLower(typ))
		files := map[string]string{
			base + "_scalar.go":     scalarFile(typ, ms),
			base + "_simd.go":       simdFile(typ, ms),
			base + "_simd_amd64.go": kernelFile(typ, ms, true),
			base + "_simd_128.go":   kernelFile(typ, ms, false),
		}
		for name, src := range files {
			if src == "" {
				if err := os.Remove(name); err != nil && !os.IsNotExist(err) {
					log.Fatal(err)
				}
				continue
			}
			formatted, err := format.Source([]byte(src))
			if err != nil {
				log.Fatalf("formatting %s: %v\n%s", name, err, src)
			}
			if err := os.WriteFile(name, formatted, 0o600); err != nil {
				log.Fatal(err)
			}
		}
	}
}
